'use client';

import { useEffect, useMemo, useState } from 'react';
import { useParams } from 'next/navigation';
import AppShell from '@/components/Navbar';
import { api } from '@/lib/api';
import type { Department, Role, UpdateUserPayload, User } from '../types';

interface UserShowResponse {
  success: boolean;
  data: User & { department?: Department };
}

interface DepartmentsResponse {
  success: boolean;
  data: Department[];
}

type ModalType = 'deactivate' | 'reactivate' | 'resetPassword' | null;

interface EditFormErrors {
  first_name?: string;
  last_name?: string;
  email?: string;
  employee_id?: string;
  student_id?: string;
}

function validate(form: { first_name: string; last_name: string; email: string; employee_id: string; student_id: string }, role: Role): EditFormErrors {
  const errors: EditFormErrors = {};
  if (!form.first_name.trim()) errors.first_name = 'First name is required.';
  if (!form.last_name.trim()) errors.last_name = 'Last name is required.';
  if (!form.email.trim()) errors.email = 'Email is required.';
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) errors.email = 'Enter a valid email.';
  if ((role === 'Admin' || role === 'Instructor') && !form.employee_id.trim()) errors.employee_id = 'Employee ID is required.';
  if (role === 'Student' && !form.student_id.trim()) errors.student_id = 'Student ID is required.';
  return errors;
}

const formatDate = (iso: string) => new Date(iso).toLocaleDateString('en-PH', { year: 'numeric', month: 'long', day: 'numeric' });

export default function AdminUserDetailPage() {
  const params = useParams<{ id: string }>();
  const userId = params?.id;

  const [user, setUser] = useState<User | null>(null);
  const [departments, setDepartments] = useState<Department[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [deptId, setDeptId] = useState<number>(0);
  const [employeeId, setEmployeeId] = useState('');
  const [studentId, setStudentId] = useState('');
  const [isIrregular, setIsIrregular] = useState(false);

  const [editErrors, setEditErrors] = useState<EditFormErrors>({});
  const [isSaving, setIsSaving] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'success' | 'error'>('idle');

  const [modal, setModal] = useState<ModalType>(null);
  const [modalLoading, setModalLoading] = useState(false);
  const [tempPassword, setTempPassword] = useState<string | null>(null);

  useEffect(() => {
    if (!userId) return;
    let mounted = true;
    (async () => {
      try {
        setLoading(true);
        setError(null);
        const [userRes, deptRes] = await Promise.all([
          api.get<UserShowResponse>(`/admin/users/${userId}`),
          api.get<DepartmentsResponse>('/admin/departments'),
        ]);
        if (!mounted) return;
        const u = userRes.data;
        setUser(u);
        setDepartments(deptRes.data ?? []);
        setFirstName(u.first_name);
        setLastName(u.last_name);
        setEmail(u.email);
        setDeptId(u.dept_id);
        setEmployeeId(u.employee_id ?? '');
        setStudentId(u.student_id ?? '');
        setIsIrregular(u.is_irregular);
      } catch (e) {
        if (!mounted) return;
        setError(e instanceof Error ? e.message : 'Failed to load user.');
      } finally {
        if (mounted) setLoading(false);
      }
    })();
    return () => {
      mounted = false;
    };
  }, [userId]);

  const isDirty = useMemo(() => {
    if (!user) return false;
    return (
      firstName !== user.first_name ||
      lastName !== user.last_name ||
      email !== user.email ||
      deptId !== user.dept_id ||
      employeeId !== (user.employee_id ?? '') ||
      studentId !== (user.student_id ?? '') ||
      isIrregular !== user.is_irregular
    );
  }, [user, firstName, lastName, email, deptId, employeeId, studentId, isIrregular]);

  const handleDiscard = () => {
    if (!user) return;
    setFirstName(user.first_name);
    setLastName(user.last_name);
    setEmail(user.email);
    setDeptId(user.dept_id);
    setEmployeeId(user.employee_id ?? '');
    setStudentId(user.student_id ?? '');
    setIsIrregular(user.is_irregular);
    setEditErrors({});
    setSaveStatus('idle');
  };

  const handleSave = async () => {
    if (!user) return;
    const errors = validate({ first_name: firstName, last_name: lastName, email, employee_id: employeeId, student_id: studentId }, user.role);
    if (Object.keys(errors).length > 0) {
      setEditErrors(errors);
      return;
    }

    try {
      setIsSaving(true);
      setSaveStatus('idle');
      const payload: UpdateUserPayload = {
        first_name: firstName.trim(),
        last_name: lastName.trim(),
        email: email.trim(),
        dept_id: deptId,
        employee_id: user.role === 'Admin' || user.role === 'Instructor' ? employeeId.trim() : null,
        student_id: user.role === 'Student' ? studentId.trim() : null,
        is_irregular: user.role === 'Student' ? isIrregular : false,
      };
      const res = await api.patch<UserShowResponse>(`/admin/users/${user.id}`, payload);
      const updated = res.data;
      setUser(updated);
      setFirstName(updated.first_name);
      setLastName(updated.last_name);
      setEmail(updated.email);
      setDeptId(updated.dept_id);
      setEmployeeId(updated.employee_id ?? '');
      setStudentId(updated.student_id ?? '');
      setIsIrregular(updated.is_irregular);
      setSaveStatus('success');
    } catch {
      setSaveStatus('error');
    } finally {
      setIsSaving(false);
    }
  };

  const handleModalConfirm = async () => {
    if (!user || !modal) return;
    try {
      setModalLoading(true);
      if (modal === 'deactivate') {
        const res = await api.post<UserShowResponse>(`/admin/users/${user.id}/deactivate`, {});
        setUser(res.data);
      } else if (modal === 'reactivate') {
        const res = await api.post<UserShowResponse>(`/admin/users/${user.id}/reactivate`, {});
        setUser(res.data);
      } else {
        const generated = `Tmp@${Math.random().toString(36).slice(2, 10)}`;
        await api.post(`/admin/users/${user.id}/reset-password`, {
          password: generated,
          password_confirmation: generated,
        });
        setTempPassword(generated);
      }
      setModal(null);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Action failed.');
    } finally {
      setModalLoading(false);
    }
  };

  if (loading) {
    return <AppShell role="admin" userName="Admin" pageTitle="User"><div className="p-6 text-sm">Loading user...</div></AppShell>;
  }
  if (!user) {
    return <AppShell role="admin" userName="Admin" pageTitle="User"><div className="p-6 text-sm text-red-600">{error ?? 'User not found.'}</div></AppShell>;
  }

  return (
    <AppShell role="admin" userName="Admin" pageTitle="User Management">
      <main className="max-w-3xl mx-auto px-4 sm:px-6 py-10 flex flex-col gap-6">
        {error && <div className="rounded border px-3 py-2 text-[12px]" style={{ borderColor: '#fecaca', background: '#fff1f2', color: '#9f1239' }}>{error}</div>}
        {tempPassword && <div className="rounded border px-3 py-2 text-[12px]">Temporary password: <span className="font-mono">{tempPassword}</span></div>}

        <section className="card card-body">
          <h1 className="text-xl font-bold">{user.first_name} {user.last_name}</h1>
          <p className="text-sm text-text-secondary">{user.email}</p>
          <p className="text-xs text-text-muted">Joined {formatDate(user.created_at)}</p>
        </section>

        <section className="card card-body flex flex-col gap-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <input value={firstName} onChange={(e) => setFirstName(e.target.value)} className="border rounded px-3 py-2 text-sm" />
            <input value={lastName} onChange={(e) => setLastName(e.target.value)} className="border rounded px-3 py-2 text-sm" />
          </div>
          <input value={email} onChange={(e) => setEmail(e.target.value)} className="border rounded px-3 py-2 text-sm" />
          <select value={deptId} onChange={(e) => setDeptId(Number(e.target.value))} className="border rounded px-3 py-2 text-sm">
            {departments.map((d) => <option key={d.id} value={d.id}>{d.code} - {d.name}</option>)}
          </select>
          {(user.role === 'Admin' || user.role === 'Instructor') && (
            <input value={employeeId} onChange={(e) => setEmployeeId(e.target.value)} className="border rounded px-3 py-2 text-sm" />
          )}
          {user.role === 'Student' && (
            <>
              <input value={studentId} onChange={(e) => setStudentId(e.target.value)} className="border rounded px-3 py-2 text-sm" />
              <label className="text-sm"><input type="checkbox" checked={isIrregular} onChange={(e) => setIsIrregular(e.target.checked)} /> Irregular</label>
            </>
          )}
          <div className="flex items-center gap-3">
            <button onClick={handleSave} disabled={!isDirty || isSaving} className="btn btn-primary">{isSaving ? 'Saving...' : 'Save Changes'}</button>
            {isDirty && <button onClick={handleDiscard} className="btn btn-outline">Discard</button>}
          </div>
          {saveStatus === 'success' && <p className="text-sm text-green-700">Profile updated successfully.</p>}
          {saveStatus === 'error' && <p className="text-sm text-red-700">Failed to update profile.</p>}
        </section>

        <section className="card card-body flex flex-wrap gap-3">
          <button onClick={() => setModal('resetPassword')} className="btn btn-outline">Reset Password</button>
          {user.is_active
            ? <button onClick={() => setModal('deactivate')} className="btn btn-danger">Deactivate</button>
            : <button onClick={() => setModal('reactivate')} className="btn btn-primary">Reactivate</button>}
        </section>

        {modal && (
          <div className="fixed inset-0 z-50 flex items-center justify-center px-4">
            <div className="absolute inset-0 bg-black/40" onClick={() => setModal(null)} />
            <div className="relative bg-white rounded-lg shadow border p-5 w-full max-w-sm">
              <p className="text-sm mb-4">Confirm {modal} action?</p>
              <div className="flex gap-2 justify-end">
                <button onClick={() => setModal(null)} className="btn btn-outline" disabled={modalLoading}>Cancel</button>
                <button onClick={handleModalConfirm} className="btn btn-primary" disabled={modalLoading}>
                  {modalLoading ? 'Processing...' : 'Confirm'}
                </button>
              </div>
            </div>
          </div>
        )}
      </main>
    </AppShell>
  );
}
